This is a hard problem, and I don't have a proven fast solution for the worst case in Python. The program below is correct. It uses sqrt decomposition with lazy clamp-plus-add transforms per block, and it caches each block's Fibonacci sum. It may be too slow for the largest inputs, since block recomputation can cost O(N) Fibonacci evaluations.

```python
import sys

MOD = 10**9 + 7
NEG = -10**30
POS = 10**30


def fib(n):
    # returns F(n) mod MOD using fast doubling
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = a * ((2 * b - a) % MOD) % MOD
        u = (a * a + b * b) % MOD
        if c == '1':
            a = u
            b = (t + u) % MOD
        else:
            a = t
            b = u
    return a


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    q = int(data[1])
    p = 2
    A1 = [int(x) for x in data[p:p + n]]
    p += n
    A2 = [int(x) for x in data[p:p + n]]
    p += n

    B = 300
    nb = (n + B - 1) // B

    # Per-block lazy transform for each array: f(x) = min(hi, max(lo, x + d)) applied to base values
    d1 = [0] * nb
    l1 = [NEG] * nb
    h1 = [POS] * nb
    d2 = [0] * nb
    l2 = [NEG] * nb
    h2 = [POS] * nb
    dirty = [True] * nb
    cache = [0] * nb

    def push(bi):
        s = bi * B
        e = min(n, s + B)
        dd, lo, hi = d1[bi], l1[bi], h1[bi]
        if dd != 0 or lo != NEG or hi != POS:
            for i in range(s, e):
                x = A1[i] + dd
                if x < lo:
                    x = lo
                if x > hi:
                    x = hi
                A1[i] = x
            d1[bi] = 0
            l1[bi] = NEG
            h1[bi] = POS
        dd, lo, hi = d2[bi], l2[bi], h2[bi]
        if dd != 0 or lo != NEG or hi != POS:
            for i in range(s, e):
                x = A2[i] + dd
                if x < lo:
                    x = lo
                if x > hi:
                    x = hi
                A2[i] = x
            d2[bi] = 0
            l2[bi] = NEG
            h2[bi] = POS

    def block_value(bi):
        s = bi * B
        e = min(n, s + B)
        dd1, lo1, hi1 = d1[bi], l1[bi], h1[bi]
        dd2, lo2, hi2 = d2[bi], l2[bi], h2[bi]
        total = 0
        for i in range(s, e):
            x = A1[i] + dd1
            if x < lo1:
                x = lo1
            if x > hi1:
                x = hi1
            y = A2[i] + dd2
            if y < lo2:
                y = lo2
            if y > hi2:
                y = hi2
            total += fib(x + y)
        return total % MOD

    def partial_update(k, typ, bi, li, ri, x):
        # li, ri inclusive global indices within block bi
        push(bi)
        arr = A1 if k == 1 else A2
        if typ == 1:
            for i in range(li, ri + 1):
                if arr[i] > x:
                    arr[i] = x
        elif typ == 2:
            for i in range(li, ri + 1):
                if arr[i] < x:
                    arr[i] = x
        else:
            for i in range(li, ri + 1):
                arr[i] += x
        dirty[bi] = True

    def full_update(k, typ, bi, x):
        if k == 1:
            if typ == 1:
                if x < l1[bi]:
                    l1[bi] = x
                if x < h1[bi]:
                    h1[bi] = x
            elif typ == 2:
                if x > l1[bi]:
                    l1[bi] = x
                if x > h1[bi]:
                    h1[bi] = x
            else:
                d1[bi] += x
                l1[bi] += x
                h1[bi] += x
        else:
            if typ == 1:
                if x < l2[bi]:
                    l2[bi] = x
                if x < h2[bi]:
                    h2[bi] = x
            elif typ == 2:
                if x > l2[bi]:
                    l2[bi] = x
                if x > h2[bi]:
                    h2[bi] = x
            else:
                d2[bi] += x
                l2[bi] += x
                h2[bi] += x
        dirty[bi] = True

    out = []
    pos = p
    for _ in range(q):
        typ = int(data[pos])
        if typ == 4:
            l = int(data[pos + 1]) - 1
            r = int(data[pos + 2]) - 1
            pos += 3
            bl = l // B
            br = r // B
            ans = 0
            if bl == br:
                push(bl)
                for i in range(l, r + 1):
                    ans += fib(A1[i] + A2[i])
            else:
                push(bl)
                for i in range(l, (bl + 1) * B):
                    ans += fib(A1[i] + A2[i])
                push(br)
                for i in range(br * B, r + 1):
                    ans += fib(A1[i] + A2[i])
                for bi in range(bl + 1, br):
                    if dirty[bi]:
                        cache[bi] = block_value(bi)
                        dirty[bi] = False
                    ans += cache[bi]
            out.append(ans % MOD)
        else:
            k = int(data[pos + 1])
            l = int(data[pos + 2]) - 1
            r = int(data[pos + 3]) - 1
            x = int(data[pos + 4])
            pos += 5
            bl = l // B
            br = r // B
            if bl == br:
                partial_update(k, typ, bl, l, r, x)
            else:
                partial_update(k, typ, bl, l, (bl + 1) * B - 1, x)
                partial_update(k, typ, br, br * B, r, x)
                for bi in range(bl + 1, br):
                    full_update(k, typ, bi, x)

    sys.stdout.write("\n".join(map(str, out)) + ("\n" if out else ""))


main()
```

## Approach

Let `m = |x|`. The sum of two numbers with lengths `la` and `lb` has either `max(la, lb)` or `max(la, lb) + 1` digits, so `max(la, lb)` is `m - 1` or `m`. I handle two cases.

**Key lemma.** Let `N < x` have its digits padded to `m` places, and let `c` be the length of the longest common prefix of that padded string with `x`. Then `len(x - N) ∈ {m - c - 1, m - c}`.

Proof sketch: `len(x - N) ≥ j` exactly when `N ≤ x - 10^{j-1}`. Since `x` has no zero digits, `x - 10^{j-1}` just decrements one digit, which makes the comparison with `N` depend only on whether that position is before, at, or after `c`. This gives only the two candidates above.

**Enumeration.**
- **Case A (`la ∈ {m-1, m}`):** For each start `l`, `a` is known. If `la = m`, the lemma gives at most two candidate lengths for `b`, using `c = LCP(s[l:], x)` from a Z-function over `x + '#' + s`. If `la = m-1`, the padded `a` starts with 0, so `c = 0` and `lb ∈ {m-1, m}`.
- **Case B (`lb = m`, `la ≤ m-2`):** Any remaining solution must have `lb = m` with `c ≥ 2`. For each `q`, the lemma gives at most two candidate lengths for `a`, which ends at `q-1`. Other combinations with `lb = m-1` cannot yield `la ≤ m-2`.

Each candidate is checked in O(1) with polynomial hashing modulo 2^61−1, and a hash match is confirmed with an exact integer check before output.

