    m = len(x)

    # Z-function on x + '#' + s gives LCP(s[i:], x) for every i (capped at m).
    T = x + '#' + s
    L = len(T)
    z = [0] * L
    lo = 0
    hi = 0
    for i in range(1, L):
        zi = 0
        if i < hi:
            zi = min(hi - i, z[i - lo])
        while i + zi < L and T[zi] == T[i + zi]:
            zi += 1
        z[i] = zi
        if i + zi > hi:
            lo = i
            hi = i + zi
    zs = z[m + 1:]

    MOD = (1 << 61) - 1
    H = [0] * (n + 1)
    P = [1] * (n + 1)
    for i, ch in enumerate(s):
