        mid = l + la
        r = mid + lb
        if r > n:
            return None
        va = (H[mid] - H[l] * P[la]) % MOD
        vb = (H[r] - H[mid] * P[lb]) % MOD
        if (va * P[lb] + vb - X) % MOD != 0:
            return None
        if Xint[0] is None:
            Xint[0] = int(x)
        if int(s[l:mid]) + int(s[mid:r]) == Xint[0]:
            return (l + 1, mid, mid + 1, r)
        return None

