The key fact is that one change is always enough when the counts differ, so the program first checks whether the string is already balanced, then tries every single-character change, and only falls back to two changes if needed. Each test case is checked by brute force over at most 2n candidate strings, which is fast for |s| ≤ 100.

```python
import sys
from itertools import product

def counts(s):
    ab = 0
    ba = 0
    for i in range(len(s) - 1):
        pair = s[i:i+2]
        if pair == 'ab':
            ab += 1
        elif pair == 'ba':
            ba += 1
    return ab, ba

def good(s):
    ab, ba = counts(s)
    return ab == ba

def solve(s):
    if good(s):
        return s
    n = len(s)
    # One change
    for i in range(n):
        for c in 'ab':
            if c != s[i]:
                t = s[:i] + c + s[i+1:]
                if good(t):
                    return t
    # Two changes (fallback; normally not needed)
    for i in range(n):
        for j in range(i + 1, n):
            for c1, c2 in product('ab', repeat=2):
                if c1 == s[i] and c2 == s[j]:
                    continue
                lst = list(s)
                lst[i] = c1
                lst[j] = c2
                t = ''.join(lst)
                if good(t):
                    return t
    return s

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for k in range(1, t + 1):
        s = data[k]
        out.append(solve(s))
    print('\n'.join(out))

if __name__ == '__main__':
    main()
```

