import sys
import bisect

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); d = int(data[1])
    base = 0
    rel = []
    idx = 2
    for _ in range(n):
        s = int(data[idx]); a = int(data[idx + 1]); idx += 2
        if a <= d <= s:
            base += 1
        elif a > d and s >= d:
            rel.append((a, s))
    rel.sort()
    m = 1 + len(rel)
    vals = [d] + [a for a, _ in rel]

    upd = {}
    groups = {}
    times = {d}
    for ti, (a, s) in enumerate(rel, start=1):
        groups.setdefault(a, []).append((ti, s))
        times.add(a)
        if s >= a:
            b = bisect.bisect_left(vals, a)
            upd.setdefault(a, []).append((b, 1))
            upd.setdefault(s + 1, []).append((b, -1))
            times.add(s + 1)

    NEG = -(1 << 60)
    N = 1; LOG = 0
    while N < m:
        N *= 2; LOG += 1
    t = [NEG] * (2 * N)
    lz = [0] * (2 * N)

    def push(k):
        v = lz[k]
        if v:
            c = 2 * k
            t[c] += v; lz[c] += v
            t[c + 1] += v; lz[c + 1] += v
            lz[k] = 0

    def range_add(l, r, v):
        if l >= r:
            return
        l += N; r += N
        for i in range(LOG, 0, -1):
            if ((l >> i) << i) != l:
                push(l >> i)
            if ((r >> i) << i) != r:
                push((r - 1) >> i)
        l2, r2 = l, r
        while l2 < r2:
            if l2 & 1:
                t[l2] += v; lz[l2] += v; l2 += 1
            if r2 & 1:
                r2 -= 1; t[r2] += v; lz[r2] += v
            l2 >>= 1; r2 >>= 1
        for i in range(1, LOG + 1):
            if ((l >> i) << i) != l:
                k = l >> i
                t[k] = max(t[2 * k], t[2 * k + 1])
            if ((r >> i) << i) != r:
                k = (r - 1) >> i
                t[k] = max(t[2 * k], t[2 * k + 1])

    def query(l, r):
        if l >= r:
            return NEG
        l += N; r += N
        for i in range(LOG, 0, -1):
            if ((l >> i) << i) != l:
                push(l >> i)
            if ((r >> i) << i) != r:
                push((r - 1) >> i)
        res = NEG
        while l < r:
            if l & 1:
                if t[l] > res: res = t[l]
                l += 1
            if r & 1:
                r -= 1
                if t[r] > res: res = t[r]
            l >>= 1; r >>= 1
        return res

    def setp(p, x):
        p += N
        for i in range(LOG, 0, -1):
            push(p >> i)
        t[p] = x
        for i in range(1, LOG + 1):
            k = p >> i
            t[k] = max(t[2 * k], t[2 * k + 1])

    ans = base
    HALF = NEG // 2
    for T in sorted(times):
        for b, delta in upd.get(T, ()):
            range_add(0, b, delta)
        if T == d:
            setp(0, base)
            continue
        g = groups.get(T)
        if g:
            res = []
            for leaf, s in g:
                M = query(0, bisect.bisect_right(vals, s))
                if M > HALF:
                    v = M + 1 - (1 if s >= T else 0)
                    res.append((leaf, v))
            for leaf, v in res:
                setp(leaf, v)
                if v > ans:
                    ans = v

    print(ans)

main()
