This uses a "Segment Tree Beats" tree that handles both arrays at once.

**Approach**

- **What a node stores.** Within a node, each element of each array is put in one of three classes. Class 0 is "equal to the node minimum". Class 1 is "equal to the node maximum" (only when max ≠ min). Class 2 is everything else. Across the two arrays this gives 3 × 3 = 9 combined classes per node.
- **Fibonacci pairs.** For each combined class the node keeps the sum of the pairs `(F(s), F(s+1))`, where `s = A1_i + A2_i`.
- **Shifting a sum.** Changing `s` by `d` is a linear map on the pair:
  - `F(s+d) = F(d)·F(s+1) + F(d-1)·F(s)`
  - `F(s+d+1) = F(d+1)·F(s+1) + F(d)·F(s)`

  This lets a whole class sum be shifted at once. Negative `d` is handled with `F(-n) = (-1)^(n+1)·F(n)`. The coefficients come from fast doubling and are cached.
- **Type 1 (chmin).** This is the standard beats rule. If `max ≤ x`, stop. If `second_max < x` and the node is fully covered, shift only the "max" class of that array by `x - max`. Otherwise recurse into the children.
- **Type 2 (chmax).** Symmetric to type 1, using the "min" class.
- **Type 3 (add).** This is a uniform shift of all 9 sums, recorded as a lazy add tag.
- **Pushdown.** First apply the add tag to both children. Then, if a child's max exceeds the parent's max, apply chmin to that child; likewise for the min with chmax.
- **Pull-up.** Each child class is mapped into a parent class. The child's min-class and max-class values are re-classified against the parent's min and max. The child's "other" class always stays "other" in the parent.
- **Type 4 (query).** Add up the 9 `F(s)` sums over the covering nodes.

```python
import sys
def main():
    data=sys.stdin.buffer.read().split()
    MOD=10**9+7
    pos=0
    n=int(data[0]); q=int(data[1]); pos=2
    A=[[int(x) for x in data[pos:pos+n]],[int(x) for x in data[pos+n:pos+2*n]]]
    pos+=2*n
    INF=1<<62; NEG=-(1<<62)
    def fibp(m):
        a,b=0,1
        for bit in bin(m)[2:]:
            c=a*(2*b-a)%MOD; e=(a*a+b*b)%MOD
            if bit=='1': a,b=e,(c+e)%MOD
            else: a,b=c,e
        return a,b
    def Fs(m):
        if m>=0: return fibp(m)[0]
        mm=-m; v=fibp(mm)[0]
        return v if mm&1 else (-v)%MOD
    cache={}
    def coef(d):
        r=cache.get(d)
        if r is None:
            if d>=0:
                a,c=fibp(d)
            else:
                a=Fs(d); c=Fs(d+1)
            r=(a,(c-a)%MOD,c)
            cache[d]=r
        return r
    size=1
    while size<n: size*=2
    T=4*n+5
    MX=[[NEG]*T for _ in range(2)]; SMX=[[NEG]*T for _ in range(2)]
    MN=[[INF]*T for _ in range(2)]; SMN=[[INF]*T for _ in range(2)]
    ADD=[[0]*T for _ in range(2)]
    F0=[0]*(9*T); F1=[0]*(9*T)
    IDX=[[[c*3+j for j in range(3)] for c in range(3)],[[j*3+c for j in range(3)] for c in range(3)]]

    def shift(node,k,cls,d):
        a,b,c=coef(d)
        base=node*9
        for j in IDX[k][cls]:
            i=base+j
            f0=F0[i]; f1=F1[i]
            if f0 or f1:
                F0[i]=(a*f1+b*f0)%MOD
                F1[i]=(c*f1+a*f0)%MOD
    def apply_add(node,k,x):
        a,b,c=coef(x)
        base=node*9
        for i in range(base,base+9):
            f0=F0[i]; f1=F1[i]
            if f0 or f1:
                F0[i]=(a*f1+b*f0)%MOD
                F1[i]=(c*f1+a*f0)%MOD
        MX[k][node]+=x; MN[k][node]+=x
        if SMX[k][node]!=NEG: SMX[k][node]+=x
        if SMN[k][node]!=INF: SMN[k][node]+=x
        ADD[k][node]+=x
    def apply_chmin(node,k,x):
        mxk=MX[k]; om=mxk[node]
        mnk=MN[k]
        cls=0 if mnk[node]==om else 1
        shift(node,k,cls,x-om)
        mxk[node]=x
        if mnk[node]==om: mnk[node]=x
        if SMN[k][node]==om: SMN[k][node]=x
    def apply_chmax(node,k,x):
        mnk=MN[k]; om=mnk[node]
        shift(node,k,0,x-om)
        mnk[node]=x
        if MX[k][node]==om: MX[k][node]=x
        if SMX[k][node]==om: SMX[k][node]=x
    def push(node):
        l=2*node; r=l+1
        for k in (0,1):
            ad=ADD[k][node]
            if ad:
                apply_add(l,k,ad); apply_add(r,k,ad); ADD[k][node]=0
            pm=MX[k][node]; pn=MN[k][node]
            for ch in (l,r):
                if MX[k][ch]>pm: apply_chmin(ch,k,pm)
                if MN[k][ch]<pn: apply_chmax(ch,k,pn)
    def pull(node):
        l=2*node; r=l+1
        for k in (0,1):
            mxk=MX[k]; smxk=SMX[k]; mnk=MN[k]; smnk=SMN[k]
            a=mxk[l]; b=mxk[r]
            if a>b: mxk[node]=a; smxk[node]=max(smxk[l],b)
            elif a<b: mxk[node]=b; smxk[node]=max(smxk[r],a)
            else: mxk[node]=a; smxk[node]=max(smxk[l],smxk[r])
            a=mnk[l]; b=mnk[r]
            if a<b: mnk[node]=a; smnk[node]=min(smnk[l],b)
            elif a>b: mnk[node]=b; smnk[node]=min(smnk[r],a)
            else: mnk[node]=a; smnk[node]=min(smnk[l],smnk[r])
        base=node*9
        s0=[0]*9; s1=[0]*9
        pmn0=MN[0][node]; pmx0=MX[0][node]; pmn1=MN[1][node]; pmx1=MX[1][node]
        for ch in (l,r):
            v=MN[0][ch]; m00=0 if v==pmn0 else (1 if v==pmx0 else 2)
            v=MX[0][ch]; m01=0 if v==pmn0 else (1 if v==pmx0 else 2)
            v=MN[1][ch]; m10=0 if v==pmn1 else (1 if v==pmx1 else 2)
            v=MX[1][ch]; m11=0 if v==pmn1 else (1 if v==pmx1 else 2)
            m1=(m00,m01,2); m2=(m10,m11,2)
            cb=ch*9
            for c1 in range(3):
                t=m1[c1]*3
                for c2 in range(3):
                    i=cb+c1*3+c2
                    f0=F0[i]; f1=F1[i]
                    if f0 or f1:
                        p=t+m2[c2]
                        s0[p]+=f0; s1[p]+=f1
        for j in range(9):
            F0[base+j]=s0[j]%MOD; F1[base+j]=s1[j]%MOD
    mxs=max(A[0][i]+A[1][i] for i in range(n))+2
    fib=[0]*(mxs+1); fib[1]=1
    for i in range(2,mxs+1): fib[i]=(fib[i-1]+fib[i-2])%MOD
    def build(node,l,r):
        if l==r:
            for k in (0,1):
                v=A[k][l]; MX[k][node]=v; MN[k][node]=v
            s=A[0][l]+A[1][l]
            F0[node*9]=fib[s]; F1[node*9]=fib[s+1]
            return
        m=(l+r)//2
        build(2*node,l,m); build(2*node+1,m+1,r); pull(node)
    sys.setrecursionlimit(10000)
    build(1,0,n-1)
    def chmin(node,l,r,ql,qr,k,x):
        if r<ql or qr<l or MX[k][node]<=x: return
        if ql<=l and r<=qr and SMX[k][node]<x:
            apply_chmin(node,k,x); return
        push(node); m=(l+r)//2
        chmin(2*node,l,m,ql,qr,k,x); chmin(2*node+1,m+1,r,ql,qr,k,x); pull(node)
    def chmax(node,l,r,ql,qr,k,x):
        if r<ql or qr<l or MN[k][node]>=x: return
        if ql<=l and r<=qr and SMN[k][node]>x:
            apply_chmax(node,k,x); return
        push(node); m=(l+r)//2
        chmax(2*node,l,m,ql,qr,k,x); chmax(2*node+1,m+1,r,ql,qr,k,x); pull(node)
    def add(node,l,r,ql,qr,k,x):
        if r<ql or qr<l: return
        if ql<=l and r<=qr:
            apply_add(node,k,x); return
        push(node); m=(l+r)//2
        add(2*node,l,m,ql,qr,k,x); add(2*node+1,m+1,r,ql,qr,k,x); pull(node)
    def query(node,l,r,ql,qr):
        if r<ql or qr<l: return 0
        if ql<=l and r<=qr:
            b=node*9
            return sum(F0[b:b+9])
        push(node); m=(l+r)//2
        return query(2*node,l,m,ql,qr)+query(2*node+1,m+1,r,ql,qr)
    out=[]
    for _ in range(q):
        t=int(data[pos]); pos+=1
        if t==4:
            l=int(data[pos])-1; r=int(data[pos+1])-1; pos+=2
            out.append(query(1,0,n-1,l,r)%MOD)
        else:
            k=int(data[pos])-1; l=int(data[pos+1])-1; r=int(data[pos+2])-1; x=int(data[pos+3]); pos+=4
            if t==1: chmin(1,0,n-1,l,r,k,x)
            elif t==2: chmax(1,0,n-1,l,r,k,x)
            else:
                if x: add(1,0,n-1,l,r,k,x)
    sys.stdout.write("\n".join(map(str,out))+("\n" if out else ""))
main()
