        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    for _ in range(t):
        n = int(data[p]); p += 1
        a = list(map(int, data[p:p+n])); p += n
        s = sum(a)
        if not prime(s):
            out.append(str(n))
            out.append(" ".join(str(i+1) for i in range(n)))
        else:
            for i in range(n):
                if a[i] % 2 == 1:
                    break
            out.append(str(n-1))
            out.append(" ".join(str(j+1) for j in range(n) if j != i))
    print("\n".join(out))
