import sys
from math import hypot

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); K = int(data[1]) - 1
    xs = [int(v) for v in data[2:2 + 2 * n:2]]
    ys = [int(v) for v in data[3:3 + 2 * n:2]]

    def cross(a, b, c):
        return (xs[b] - xs[a]) * (ys[c] - ys[a]) - (ys[b] - ys[a]) * (xs[c] - xs[a])

    def solve(o, a, b):
        dx = xs[b] - xs[a]
        dy = ys[b] - ys[a]
        ln = hypot(dx, dy)
        best_l = None
        best_r = None
        tl = float('inf')
        tr = float('-inf')
        tk = 0.0
        for i in range(n):
            if i == o:
                continue
            t = ((xs[i] - xs[a]) * dx + (ys[i] - ys[a]) * dy) / ln
            if t < tl:
                tl = t; best_l = i
            if t > tr:
                tr = t; best_r = i
            if i == K:
                tk = t
        L = tl; R = tr
        dPL = hypot(xs[o] - xs[best_l], ys[o] - ys[best_l])
        dPR = hypot(xs[o] - xs[best_r], ys[o] - ys[best_r])
        if K == o:
            return min(dPL, dPR) + R - L
        k = tk
        dPk = hypot(xs[o] - xs[K], ys[o] - ys[K])
        o1 = (k - L) + (R - L) + dPR
        o2 = (R - k) + (R - L) + dPL
        o3 = (k - L) + dPL + min(dPk, dPR) + (R - k)
        o4 = (R - k) + dPR + min(dPk, dPL) + (k - L)
        o5 = dPk + min(dPL, dPR) + (R - L)
        return min(o1, o2, o3, o4, o5)

    if cross(0, 1, 2) == 0:
        o = -1
        for i in range(3, n):
            if cross(0, 1, i) != 0:
                o = i
                break
        ans = solve(o, 0, 1)
    else:
        if n == 3:
            ans = min(solve(0, 1, 2), solve(1, 0, 2), solve(2, 0, 1))
        else:
            ans = None
            for o, a, b in ((0, 1, 2), (1, 0, 2), (2, 0, 1)):
                if cross(a, b, 3) == 0:
                    ans = solve(o, a, b)
                    break
            if ans is None:
                ans = solve(0, 1, 2)
    print("%.9f" % ans)

main()
